// Build Error Payload
// Reads the Error Trigger payload and prepares a safe JSON string for the
// Postgres insert. Escapes single quotes for the SQL string literal.

const event = $input.first().json;

const executionId = event.execution && event.execution.id
  ? String(event.execution.id)
  : `unknown_${Date.now()}`;

const gcalEventId = `error_exec_${executionId}`;

// Escape single quotes for Postgres string literal
const rawJsonEscaped = JSON.stringify(event).replace(/'/g, "''");

return [{
  json: {
    gcal_event_id: gcalEventId,
    slack_post_status: 'failed',
    oauth_refresh_status: 'failed',
    oauth_error: rawJsonEscaped,
    event_summary: 'Error handler triggered'
  }
}];
